/* ---------------------------------------------------------
   KALYM FITWEAR — App de Gestão
   Paleta oficial: champagne / preto / dourado
   Logo oficial embutida em base64 (sem recriação vetorial)
--------------------------------------------------------- */

export const LOGO_B64 = "";
const C = {
  bg: "#F2E8D6",
  bgSoft: "#FBF6EC",
  card: "#FFFFFF",
  black: "#15130F",
  ink: "#2B2620",
  gold: "#C9A24B",
  goldDeep: "#A9832E",
  line: "#E4D8BE",
  danger: "#B3402E",
  dangerBg: "#F6E1DA",
  green: "#4C6B4F",
  greenBg: "#E4EBDE",
  muted: "#8A7F68",
};

const STORAGE_KEY = "kalym-financeiro-v1";
const CATEGORIES = ["Marketing", "Embalagem", "Imposto", "Ferramentas", "Frete", "Outros"];
const CHANNELS = ["Instagram", "WhatsApp", "Indicação", "Outro"];

function uid() {
  return (crypto?.randomUUID?.() || `id-${Date.now()}-${Math.random().toString(16).slice(2)}`);
}
function brl(v) {
  const n = Number(v) || 0;
  return n.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
}
function todayISO() { return new Date().toISOString().slice(0, 10); }
function monthKey(dateStr) { return (dateStr || "").slice(0, 7); }
function roundUpTo90(x) {
  if (!isFinite(x) || x <= 0) return 0;
  const floor = Math.floor(x);
  let candidate = floor + 0.9;
  if (candidate < x - 0.001) candidate += 1;
  return Math.round(candidate * 100) / 100;
}

/* Logo oficial — imagem original embutida, sem recriação vetorial */
function Logo({ size = 26 }) {
  return (
    <img
      src={`data:image/png;base64,${LOGO_B64}`}
      alt="Kalym Fitwear"
      width={size}
      height={size}
      style={{ display: "block", borderRadius: 4 }}
    />
  );
}

/* ---------------------------------------------------------
   Dados padrão (seed)
--------------------------------------------------------- */
const DEFAULT_DATA = {
  params: { targetMargin: 0.45, taxRate: 0.06, round90: true },
  paymentMethods: [
    { id: uid(), name: "Pix", hasFee: true, feeRate: 0.0199, allowsInstallments: false },
    { id: uid(), name: "Cartão", hasFee: true, feeRate: 0.045, allowsInstallments: true },
    { id: uid(), name: "Dinheiro", hasFee: false, feeRate: 0, allowsInstallments: false },
  ],
  installments: [],
  costLibrary: [
    { id: uid(), name: "Embalagem", value: 3.5 },
    { id: uid(), name: "Etiqueta/Tag", value: 1.0 },
    { id: uid(), name: "Frete médio", value: 15.0 },
  ],
  products: [],
  sales: [],
  expenses: [],
  expenseTemplates: [],
  transfers: [],
  meta: { createdAt: todayISO() },
};

/* ---------------------------------------------------------
   Migração — garante que dados salvos em versões antigas
   do app ganhem os campos novos (paymentMethods, installments etc.)
--------------------------------------------------------- */
function normalizeData(d) {
  if (!d) return d;
  const out = { ...d };

  if (!Array.isArray(out.paymentMethods)) {
    const oldParams = out.params || {};
    out.paymentMethods = [
      { id: uid(), name: "Pix", hasFee: true, feeRate: Number(oldParams.pixFee ?? 0.0199), allowsInstallments: false },
      { id: uid(), name: "Cartão", hasFee: true, feeRate: Number(oldParams.cardFee ?? 0.045), allowsInstallments: true },
      { id: uid(), name: "Dinheiro", hasFee: false, feeRate: 0, allowsInstallments: false },
    ];
  }
  if (!Array.isArray(out.installments)) out.installments = [];
  if (!Array.isArray(out.costLibrary)) out.costLibrary = [];
  if (!Array.isArray(out.products)) out.products = [];
  if (!Array.isArray(out.sales)) out.sales = [];
  if (!Array.isArray(out.expenses)) out.expenses = [];
  if (!Array.isArray(out.expenseTemplates)) out.expenseTemplates = [];
  if (!Array.isArray(out.transfers)) out.transfers = [];

  const oldParams = out.params || {};
  out.params = {
    targetMargin: Number(oldParams.targetMargin ?? oldParams.margemMeta ?? 0.45),
    taxRate: Number(oldParams.taxRate ?? 0.06),
    round90: oldParams.round90 !== undefined ? !!oldParams.round90 : true,
  };

  // Vendas antigas (formato com paymentMethod único em vez de payments[])
  out.sales = out.sales.map((s) => {
    if (Array.isArray(s.payments)) return s;
    const methodId = out.paymentMethods.find((m) =>
      s.paymentMethod === "pix" ? m.name === "Pix" : s.paymentMethod === "cartao" ? m.name === "Cartão" : m.name === "Dinheiro"
    )?.id || out.paymentMethods[0]?.id;
    const amount = s.isPartial ? Number(s.amountReceived || 0) : Number(s.finalPrice || 0);
    return { ...s, payments: amount > 0 ? [{ id: uid(), paymentMethodId: methodId, amount, installmentId: null }] : [] };
  });

  return out;
}

/* ---------------------------------------------------------
   Storage helpers
--------------------------------------------------------- */
async function loadData() {
  try {
    const res = await window.storage.get(STORAGE_KEY, true);
    if (res && res.value) return { data: normalizeData(JSON.parse(res.value)), reason: null };
  } catch (e) {
    try {
      const local = localStorage.getItem(STORAGE_KEY + "-fallback");
      if (local) return { data: normalizeData(JSON.parse(local)), reason: (e && e.message) || String(e), fromLocalFallback: true };
    } catch (_) {}
    return { data: null, reason: (e && e.message) || String(e) };
  }
  return { data: null, reason: null };
}
async function saveData(data) {
  try {
    const res = await window.storage.set(STORAGE_KEY, JSON.stringify(data), true);
    if (!res) return { ok: false, reason: "Resposta vazia do storage compartilhado." };
    try { localStorage.setItem(STORAGE_KEY + "-fallback", JSON.stringify(data)); } catch (_) {}
    return { ok: true };
  } catch (e) {
    try {
      localStorage.setItem(STORAGE_KEY + "-fallback", JSON.stringify(data));
      return { ok: false, reason: (e && e.message) || String(e), localFallback: true };
    } catch (e2) {
      return { ok: false, reason: (e && e.message) || String(e), localFallback: false };
    }
  }
}

/* ---------------------------------------------------------
   Cálculo de custo de produto
--------------------------------------------------------- */
function productUnitCost(product, costLibrary) {
  if (!product) return 0;
  const applied = (product.appliedCostIds || [])
    .map((id) => costLibrary.find((c) => c.id === id))
    .filter(Boolean)
    .reduce((s, c) => s + Number(c.value || 0), 0);
  return Number(product.baseCost || 0) + applied;
}

/* Taxa efetiva de uma linha de pagamento (considera parcelamento) */
function lineFeeRate(line, data) {
  const method = data.paymentMethods.find((m) => m.id === line.paymentMethodId);
  if (!method) return 0;
  if (line.installmentId) {
    const inst = data.installments.find((i) => i.id === line.installmentId);
    if (inst) return Number(inst.feeRate || 0);
  }
  return method.hasFee ? Number(method.feeRate || 0) : 0;
}

function paymentsTotal(payments) {
  return (payments || []).reduce((s, p) => s + Number(p.amount || 0), 0);
}

/* ---------------------------------------------------------
   App
--------------------------------------------------------- */
export default function App() {
  const [data, setData] = useState(null);
  const [tab, setTab] = useState("inicio");
  const [saveState, setSaveState] = useState("idle");
  const [saveError, setSaveError] = useState(null);
  const saveTimer = useRef(null);
  const firstLoad = useRef(true);
  const [isWide, setIsWide] = useState(typeof window !== "undefined" ? window.innerWidth >= 720 : false);

  useEffect(() => {
    function onResize() { setIsWide(window.innerWidth >= 720); }
    window.addEventListener("resize", onResize);
    return () => window.removeEventListener("resize", onResize);
  }, []);

  useEffect(() => {
    (async () => {
      const result = await loadData();
      let loaded = result.data;
      if (!loaded) {
        loaded = DEFAULT_DATA;
        const saveResult = await saveData(loaded);
        if (!saveResult.ok) { setSaveState(saveResult.localFallback ? "local" : "error"); setSaveError(saveResult.reason); }
      } else if (result.fromLocalFallback) {
        setSaveState("local");
        setSaveError(result.reason);
      }
      loaded = applyRecurringExpenses(loaded);
      setData(loaded);
    })();
  }, []);

  useEffect(() => {
    if (!data) return;
    if (firstLoad.current) { firstLoad.current = false; return; }
    setSaveState("saving");
    if (saveTimer.current) clearTimeout(saveTimer.current);
    saveTimer.current = setTimeout(async () => {
      const result = await saveData(data);
      if (result.ok) { setSaveState("idle"); setSaveError(null); }
      else { setSaveState(result.localFallback ? "local" : "error"); setSaveError(result.reason); }
    }, 400);
    return () => clearTimeout(saveTimer.current);
  }, [data]);

  function applyRecurringExpenses(d) {
    const mk = monthKey(todayISO());
    const newExpenses = [...d.expenses];
    let changed = false;
    (d.expenseTemplates || []).forEach((tpl) => {
      const exists = newExpenses.some((e) => e.templateId === tpl.id && monthKey(e.date) === mk);
      if (!exists) {
        newExpenses.push({
          id: uid(), date: todayISO(), name: tpl.name, category: tpl.category,
          amount: tpl.amount, account: tpl.account, recurring: true, templateId: tpl.id,
        });
        changed = true;
      }
    });
    if (!changed) return d;
    return { ...d, expenses: newExpenses };
  }

  if (!data) {
    return (
      <div style={{ background: C.bg, minHeight: "100%", display: "flex", alignItems: "center", justifyContent: "center", padding: 40 }}>
        <div style={{ textAlign: "center", color: C.muted }}>
          <div style={{ marginBottom: 12, display: "flex", justifyContent: "center" }}><Logo size={40} /></div>
          Carregando dados da Kalym…
        </div>
      </div>
    );
  }

  const tabs = [
    { id: "inicio", label: "Início", icon: Home },
    { id: "vendas", label: "Vendas", icon: ShoppingBag },
    { id: "estoque", label: "Estoque", icon: Package },
    { id: "financeiro", label: "Financeiro", icon: Wallet },
    { id: "precos", label: "Preços", icon: Calculator },
  ];

  return (
    <div style={{ background: C.bg, minHeight: "100%", fontFamily: "Arial, sans-serif", color: C.ink, paddingBottom: isWide ? 24 : 88 }}>
      <style>{`
        * { box-sizing: border-box; }
        input, select, textarea { font-family: Arial, sans-serif; }
        input:focus, select:focus, textarea:focus { outline: 2px solid ${C.gold}; outline-offset: 1px; }
        button { cursor: pointer; font-family: Arial, sans-serif; }
        ::-webkit-scrollbar { width: 6px; }
      `}</style>

      <Header saveState={saveState} saveError={saveError} tabs={tabs} active={tab} onChange={setTab} isWide={isWide} />

      <div style={{ display: "flex", maxWidth: isWide ? 960 : 480, margin: "0 auto" }}>
        {isWide && <SideNav tabs={tabs} active={tab} onChange={setTab} />}
        <main style={{ flex: 1, padding: "0 16px", minWidth: 0 }}>
          {saveState === "local" && (
            <div style={{ background: C.dangerBg, color: C.danger, borderRadius: 10, padding: "10px 14px", fontSize: 12, marginTop: 14 }}>
              Não consegui salvar no servidor compartilhado — seus dados estão sendo guardados só neste celular por enquanto. Assim que possível, exporte um backup (Início → Backup) pra não correr risco de perder algo.
            </div>
          )}
          {tab === "inicio" && <Dashboard data={data} setData={setData} goTo={setTab} />}
          {tab === "vendas" && <SalesTab data={data} setData={setData} />}
          {tab === "estoque" && <StockTab data={data} setData={setData} />}
          {tab === "financeiro" && <FinanceTab data={data} setData={setData} />}
          {tab === "precos" && <PricingTab data={data} setData={setData} />}
        </main>
      </div>

      {!isWide && <BottomNav tabs={tabs} active={tab} onChange={setTab} />}
    </div>
  );
}

function Header({ saveState, saveError, isWide }) {
  return (
    <div style={{ background: C.black, padding: "18px 16px 16px" }}>
      <div style={{ maxWidth: isWide ? 960 : 480, margin: "0 auto", display: "flex", alignItems: "center", gap: 10 }}>
        <Logo size={28} />
        <div>
          <div style={{ color: C.bg, fontFamily: "Georgia, serif", fontSize: 18, letterSpacing: 3 }}>KALYM</div>
          <div style={{ color: C.gold, fontSize: 9, letterSpacing: 2 }}>GESTÃO FINANCEIRA</div>
        </div>
        <button
          onClick={() => saveError && alert("Detalhe do erro de salvamento:\n\n" + saveError)}
          style={{ marginLeft: "auto", fontSize: 10, color: saveState === "error" ? "#E29999" : saveState === "local" ? "#E2C08D" : C.muted, background: "none", border: "none", padding: 0 }}
        >
          {saveState === "saving" && "salvando…"}
          {saveState === "idle" && "salvo"}
          {saveState === "error" && "erro ao salvar (tocar p/ detalhe)"}
          {saveState === "local" && "salvo só neste celular"}
        </button>
      </div>
    </div>
  );
}

function SideNav({ tabs, active, onChange }) {
  return (
    <nav style={{ width: 180, paddingTop: 20, borderRight: `1px solid ${C.line}` }}>
      {tabs.map((t) => {
        const Icon = t.icon;
        const isActive = active === t.id;
        return (
          <button key={t.id} onClick={() => onChange(t.id)} style={{
            width: "100%", background: isActive ? C.card : "none", border: "none", display: "flex",
            alignItems: "center", gap: 10, padding: "10px 14px", borderRadius: 10, marginBottom: 4,
            color: isActive ? C.black : C.muted, fontWeight: isActive ? 700 : 400, fontSize: 13,
          }}>
            <Icon size={17} /> {t.label}
          </button>
        );
      })}
    </nav>
  );
}

function BottomNav({ tabs, active, onChange }) {
  return (
    <nav style={{
      position: "fixed", bottom: 0, left: 0, right: 0, background: C.black,
      display: "flex", justifyContent: "space-around", padding: "8px 4px 10px", zIndex: 10,
      boxShadow: "0 -2px 12px rgba(0,0,0,0.25)"
    }}>
      {tabs.map((t) => {
        const Icon = t.icon;
        const isActive = active === t.id;
        return (
          <button key={t.id} onClick={() => onChange(t.id)} style={{
            background: "none", border: "none", display: "flex", flexDirection: "column",
            alignItems: "center", gap: 3, color: isActive ? C.gold : "#8B8578", padding: "4px 8px",
          }}>
            <Icon size={20} strokeWidth={isActive ? 2.4 : 1.8} />
            <span style={{ fontSize: 10 }}>{t.label}</span>
          </button>
        );
      })}
    </nav>
  );
}

