/* ---------------------------------------------------------
   Cálculos financeiros compartilhados
--------------------------------------------------------- */
function useMonthlyReport(data) {
  return useMemo(() => {
    const mk = monthKey(todayISO());
    const salesMonth = data.sales.filter((s) => monthKey(s.date) === mk);
    const expensesMonth = data.expenses.filter((e) => monthKey(e.date) === mk && e.account === "business");

    let receitaBruta = 0, taxasPagas = 0, impostoPago = 0, cogs = 0;
    const byProduct = {};

    salesMonth.forEach((s) => {
      receitaBruta += Number(s.finalPrice || 0);
      impostoPago += Number(s.finalPrice || 0) * (data.params.taxRate || 0);
      (s.payments || []).forEach((p) => { taxasPagas += Number(p.amount || 0) * lineFeeRate(p, data); });
      cogs += Number(s.costSnapshot || 0);

      if (!byProduct[s.productId]) byProduct[s.productId] = { qty: 0, revenue: 0, cost: 0 };
      byProduct[s.productId].qty += Number(s.qty || 0);
      byProduct[s.productId].revenue += Number(s.finalPrice || 0);
      byProduct[s.productId].cost += Number(s.costSnapshot || 0);
    });

    const despesasMes = expensesMonth.reduce((sum, e) => sum + Number(e.amount || 0), 0);
    const lucro = receitaBruta - taxasPagas - impostoPago - cogs - despesasMes;

    const ranking = Object.entries(byProduct).map(([productId, v]) => {
      const product = data.products.find((p) => p.id === productId);
      return { productId, name: product?.name || "Produto removido", qty: v.qty, revenue: v.revenue, profit: v.revenue - v.cost };
    });

    return { mk, salesMonth, receitaBruta, taxasPagas, impostoPago, cogs, despesasMes, lucro, ranking, vendasCount: salesMonth.length };
  }, [data]);
}

function useCashBalances(data) {
  return useMemo(() => {
    let business = 0, personal = 0;
    data.sales.forEach((s) => {
      const taxAmount = Number(s.finalPrice || 0) * (data.params.taxRate || 0);
      let netFromPayments = 0;
      (s.payments || []).forEach((p) => { netFromPayments += Number(p.amount || 0) * (1 - lineFeeRate(p, data)); });
      business += netFromPayments - taxAmount;
    });
    data.expenses.forEach((e) => {
      if (e.account === "business") business -= Number(e.amount || 0);
      else personal -= Number(e.amount || 0);
    });
    data.transfers.forEach((t) => {
      if (t.type === "retirada") { business -= Number(t.amount || 0); personal += Number(t.amount || 0); }
      else { business += Number(t.amount || 0); personal -= Number(t.amount || 0); }
    });
    return { business, personal };
  }, [data]);
}

function usePending(data) {
  return useMemo(() => data.sales.filter((s) => s.isPartial && Number(s.pending || 0) > 0.009), [data]);
}

/* ---------------------------------------------------------
   INÍCIO / DASHBOARD
--------------------------------------------------------- */
function Dashboard({ data, setData, goTo }) {
  const report = useMonthlyReport(data);
  const cash = useCashBalances(data);
  const pending = usePending(data);
  const lowStock = data.products.filter((p) => Number(p.stockQty) <= 3);

  return (
    <div>
      <Section title="Resumo do mês">
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
          <Card><div style={{ fontSize: 11, color: C.muted }}>Lucro do mês</div><div style={{ fontSize: 20, fontWeight: 700, color: report.lucro >= 0 ? C.green : C.danger }}>{brl(report.lucro)}</div></Card>
          <Card><div style={{ fontSize: 11, color: C.muted }}>Saldo em caixa (empresa)</div><div style={{ fontSize: 20, fontWeight: 700 }}>{brl(cash.business)}</div></Card>
          <Card><div style={{ fontSize: 11, color: C.muted }}>Vendas do mês</div><div style={{ fontSize: 20, fontWeight: 700 }}>{report.vendasCount}</div><div style={{ fontSize: 11, color: C.muted }}>{brl(report.receitaBruta)}</div></Card>
          <Card><div style={{ fontSize: 11, color: C.muted }}>Caixa pessoal</div><div style={{ fontSize: 20, fontWeight: 700 }}>{brl(cash.personal)}</div></Card>
        </div>
      </Section>

      {lowStock.length > 0 && (
        <Section title="Estoque baixo">
          <Card style={{ borderColor: C.gold }}>
            {lowStock.map((p) => (
              <div key={p.id} style={{ display: "flex", justifyContent: "space-between", padding: "6px 0", fontSize: 13 }}>
                <span style={{ display: "flex", alignItems: "center", gap: 6 }}><AlertTriangle size={14} color={C.goldDeep} /> {p.name}</span>
                <span style={{ fontWeight: 700 }}>{p.stockQty} un.</span>
              </div>
            ))}
            <div style={{ marginTop: 8 }}>
              <button onClick={() => goTo("estoque")} style={{ background: "none", border: "none", color: C.goldDeep, fontSize: 12, display: "flex", alignItems: "center", gap: 4 }}>
                Repor estoque <ChevronRight size={14} />
              </button>
            </div>
          </Card>
        </Section>
      )}

      {pending.length > 0 && (
        <Section title="Contas a receber">
          <Card>
            {pending.map((s) => (
              <div key={s.id} style={{ display: "flex", justifyContent: "space-between", padding: "6px 0", fontSize: 13 }}>
                <span style={{ display: "flex", alignItems: "center", gap: 6 }}><Clock size={14} color={C.goldDeep} /> {s.clientName || "Cliente"} — vence {s.dueDate ? new Date(s.dueDate + "T00:00:00").toLocaleDateString("pt-BR") : "-"}</span>
                <span style={{ fontWeight: 700 }}>{brl(s.pending)}</span>
              </div>
            ))}
          </Card>
        </Section>
      )}

      {data.products.length === 0 && (
        <Section title="Começando">
          <Card>
            <div style={{ fontSize: 13, marginBottom: 10 }}>Cadastre seu primeiro produto pra começar a usar o app.</div>
            <IconButton variant="gold" onClick={() => goTo("estoque")}><Plus size={15} /> Cadastrar produto</IconButton>
          </Card>
        </Section>
      )}

      <BackupSection data={data} setData={setData} />
    </div>
  );
}

function BackupSection({ data, setData }) {
  const fileInputRef = useRef(null);
  const [confirming, setConfirming] = useState(false);

  function handleExport() {
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url; a.download = `kalym-backup-${todayISO()}.json`;
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    URL.revokeObjectURL(url);
  }
  function handleImportFile(e) {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => {
      try {
        const parsed = JSON.parse(reader.result);
        if (!parsed || typeof parsed !== "object" || !("products" in parsed)) {
          alert("Arquivo inválido — não parece ser um backup da Kalym.");
          return;
        }
        setData(parsed);
        setConfirming(false);
      } catch { alert("Não consegui ler esse arquivo. Confirme que é um backup .json exportado daqui."); }
    };
    reader.readAsText(file);
    e.target.value = "";
  }

  return (
    <Section title="Backup dos dados">
      <Card>
        <div style={{ fontSize: 12, color: C.muted, marginBottom: 10 }}>
          Exporta uma cópia de tudo (produtos, vendas, despesas) em um arquivo .json — guarde de vez em quando.
        </div>
        <div style={{ display: "flex", gap: 8 }}>
          <IconButton variant="ghost" onClick={handleExport}><Download size={14} /> Exportar backup</IconButton>
          <IconButton variant="ghost" onClick={() => setConfirming(true)}><Upload size={14} /> Importar backup</IconButton>
        </div>
        <input ref={fileInputRef} type="file" accept="application/json" style={{ display: "none" }} onChange={handleImportFile} />
      </Card>
      {confirming && (
        <Modal title="Importar backup" onClose={() => setConfirming(false)}>
          <div style={{ fontSize: 13, marginBottom: 14 }}>
            Isso vai <strong>substituir todos os dados atuais</strong> pelos do arquivo importado. Essa ação não pode ser desfeita. Tem certeza?
          </div>
          <IconButton variant="danger" style={{ width: "100%", justifyContent: "center", marginBottom: 8 }} onClick={() => fileInputRef.current?.click()}>Escolher arquivo e substituir</IconButton>
          <IconButton variant="ghost" style={{ width: "100%", justifyContent: "center" }} onClick={() => setConfirming(false)}>Cancelar</IconButton>
        </Modal>
      )}
    </Section>
  );
}

/* ---------------------------------------------------------
   VENDAS
--------------------------------------------------------- */
function SalesTab({ data, setData }) {
  const [showForm, setShowForm] = useState(false);
  const [receivingSale, setReceivingSale] = useState(null);
  const sorted = [...data.sales].sort((a, b) => (b.date > a.date ? 1 : -1));

  function removeSale(saleId) {
    setData((d) => {
      const sale = d.sales.find((s) => s.id === saleId);
      const products = d.products.map((p) => p.id === sale?.productId ? { ...p, stockQty: Number(p.stockQty) + Number(sale.qty) } : p);
      return { ...d, sales: d.sales.filter((s) => s.id !== saleId), products };
    });
  }

  function methodName(id) { return data.paymentMethods.find((m) => m.id === id)?.name || "—"; }

  return (
    <div>
      <Section title="Vendas" action={
        <IconButton variant="gold" onClick={() => setShowForm(true)} disabled={data.products.length === 0}><Plus size={15} /> Nova venda</IconButton>
      }>
        {data.products.length === 0 && <Empty text="Cadastre um produto na aba Estoque antes de registrar vendas." />}
        {data.products.length > 0 && sorted.length === 0 && <Empty text="Nenhuma venda registrada ainda." />}
        {sorted.map((s) => {
          const product = data.products.find((p) => p.id === s.productId);
          return (
            <Card key={s.id} style={{ marginBottom: 10 }}>
              <div style={{ display: "flex", justifyContent: "space-between" }}>
                <div>
                  <div style={{ fontWeight: 700, fontSize: 14 }}>{product?.name || "Produto"} × {s.qty}</div>
                  <div style={{ fontSize: 11, color: C.muted }}>
                    {new Date(s.date + "T00:00:00").toLocaleDateString("pt-BR")} · {(s.payments || []).map((p) => methodName(p.paymentMethodId)).join(" + ") || "—"}
                    {s.clientName ? ` · ${s.clientName}` : ""}
                  </div>
                </div>
                <div style={{ textAlign: "right" }}>
                  <div style={{ fontWeight: 700 }}>{brl(s.finalPrice)}</div>
                  {s.discount > 0 && <div style={{ fontSize: 11, color: C.muted }}>desconto {brl(s.discount)}</div>}
                </div>
              </div>
              {s.isPartial && Number(s.pending) > 0.009 && (
                <div style={{ marginTop: 8, display: "flex", justifyContent: "space-between", alignItems: "center", background: C.dangerBg, borderRadius: 8, padding: "6px 10px" }}>
                  <span style={{ fontSize: 12, color: C.danger }}>Falta receber {brl(s.pending)}</span>
                  <button onClick={() => setReceivingSale(s)} style={{ background: "none", border: "none", color: C.danger, fontSize: 12, display: "flex", alignItems: "center", gap: 3 }}>
                    <Check size={13} /> Marcar recebido
                  </button>
                </div>
              )}
              <div style={{ marginTop: 8, textAlign: "right" }}>
                <button onClick={() => removeSale(s.id)} style={{ background: "none", border: "none", color: C.muted, fontSize: 11, display: "inline-flex", alignItems: "center", gap: 3 }}>
                  <Trash2 size={12} /> excluir (devolve estoque)
                </button>
              </div>
            </Card>
          );
        })}
      </Section>

      {showForm && <SaleForm data={data} setData={setData} onClose={() => setShowForm(false)} />}
      {receivingSale && <ReceiveForm data={data} setData={setData} sale={receivingSale} onClose={() => setReceivingSale(null)} />}
    </div>
  );
}

function ReceiveForm({ data, setData, sale, onClose }) {
  const [methodId, setMethodId] = useState(data.paymentMethods[0]?.id || "");

  function submit() {
    setData((d) => ({
      ...d,
      sales: d.sales.map((s) => {
        if (s.id !== sale.id) return s;
        const newPayments = [...(s.payments || []), { id: uid(), paymentMethodId: methodId, amount: s.pending, installmentId: null }];
        return { ...s, payments: newPayments, pending: 0, isPartial: false };
      }),
    }));
    onClose();
  }

  return (
    <Modal title="Marcar como recebido" onClose={onClose} z={60}>
      <div style={{ fontSize: 13, marginBottom: 12 }}>Valor pendente: <strong>{brl(sale.pending)}</strong></div>
      <Field label="Recebido via">
        <select style={inputStyle} value={methodId} onChange={(e) => setMethodId(e.target.value)}>
          {data.paymentMethods.map((m) => <option key={m.id} value={m.id}>{m.name}</option>)}
        </select>
      </Field>
      <IconButton variant="gold" style={{ width: "100%", justifyContent: "center" }} onClick={submit}>Confirmar recebimento</IconButton>
    </Modal>
  );
}

function SaleForm({ data, setData, onClose }) {
  const [productId, setProductId] = useState(data.products[0]?.id || "");
  const [qty, setQty] = useState(1);
  const [listPrice, setListPrice] = useState(0);
  const [discount, setDiscount] = useState(0);
  const [channel, setChannel] = useState("");
  const [clientName, setClientName] = useState("");
  const [clientContact, setClientContact] = useState("");
  const [isPartial, setIsPartial] = useState(false);
  const [dueDate, setDueDate] = useState("");
  const [payments, setPayments] = useState([{ id: uid(), paymentMethodId: data.paymentMethods[0]?.id || "", amount: 0, installmentId: null }]);

  const product = data.products.find((p) => p.id === productId);
  useEffect(() => { if (product) setListPrice(Number(product.salePrice || 0)); }, [productId]);

  const finalPrice = Math.max(0, Number(listPrice || 0) - Number(discount || 0));
  const totalPaid = paymentsTotal(payments);
  const diff = Math.round((totalPaid - finalPrice) * 100) / 100;
  const pending = isPartial ? Math.max(0, finalPrice - totalPaid) : 0;

  function updateLine(id, patch) {
    setPayments((lines) => lines.map((l) => l.id === id ? { ...l, ...patch } : l));
  }
  function addLine() {
    setPayments((lines) => [...lines, { id: uid(), paymentMethodId: data.paymentMethods[0]?.id || "", amount: 0, installmentId: null }]);
  }
  function removeLine(id) {
    setPayments((lines) => lines.filter((l) => l.id !== id));
  }

  function submit() {
    if (!product) return;
    const unitCost = productUnitCost(product, data.costLibrary);
    const sale = {
      id: uid(), date: todayISO(), productId, qty: Number(qty || 1),
      listPrice: Number(listPrice || 0), discount: Number(discount || 0), finalPrice,
      channel: channel || null, clientName: clientName || null, clientContact: clientContact || null,
      isPartial, pending, dueDate: isPartial ? dueDate || null : null,
      payments: payments.filter((p) => Number(p.amount) > 0),
      costSnapshot: unitCost * Number(qty || 1),
    };
    setData((d) => ({
      ...d,
      sales: [...d.sales, sale],
      products: d.products.map((p) => p.id === productId ? { ...p, stockQty: Math.max(0, Number(p.stockQty) - Number(qty || 1)) } : p),
    }));
    onClose();
  }

  return (
    <Modal title="Nova venda" onClose={onClose}>
      <Field label="Produto">
        <select style={inputStyle} value={productId} onChange={(e) => setProductId(e.target.value)}>
          {data.products.map((p) => <option key={p.id} value={p.id}>{p.name} ({p.stockQty} em estoque)</option>)}
        </select>
      </Field>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
        <Field label="Quantidade"><input type="number" min="1" style={inputStyle} value={qty} onChange={(e) => setQty(e.target.value)} /></Field>
        <Field label="Preço de tabela (R$)"><input type="number" step="0.01" style={inputStyle} value={listPrice} onChange={(e) => setListPrice(e.target.value)} /></Field>
      </div>
      <Field label="Desconto (R$)"><input type="number" step="0.01" style={inputStyle} value={discount} onChange={(e) => setDiscount(e.target.value)} /></Field>
      <div style={{ background: C.bgSoft, borderRadius: 8, padding: "8px 12px", marginBottom: 12, fontSize: 13 }}>
        Preço final: <strong>{brl(finalPrice)}</strong>
      </div>

      <Field label="Canal (opcional)">
        <select style={inputStyle} value={channel} onChange={(e) => setChannel(e.target.value)}>
          <option value="">—</option>
          {CHANNELS.map((c) => <option key={c} value={c}>{c}</option>)}
        </select>
      </Field>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
        <Field label="Cliente (opcional)"><input style={inputStyle} value={clientName} onChange={(e) => setClientName(e.target.value)} /></Field>
        <Field label="Contato (opcional)"><input style={inputStyle} value={clientContact} onChange={(e) => setClientContact(e.target.value)} /></Field>
      </div>

      <div style={{ fontSize: 11, color: C.muted, marginBottom: 6, marginTop: 6 }}>Formas de pagamento</div>
      {payments.map((line) => {
        const method = data.paymentMethods.find((m) => m.id === line.paymentMethodId);
        return (
          <div key={line.id} style={{ display: "flex", gap: 6, marginBottom: 8, alignItems: "flex-start" }}>
            <select style={{ ...inputStyle, flex: "1 1 auto" }} value={line.paymentMethodId} onChange={(e) => updateLine(line.id, { paymentMethodId: e.target.value, installmentId: null })}>
              {data.paymentMethods.map((m) => <option key={m.id} value={m.id}>{m.name}</option>)}
            </select>
            <input type="number" step="0.01" placeholder="R$" style={{ ...inputStyle, width: 90 }} value={line.amount} onChange={(e) => updateLine(line.id, { amount: e.target.value })} />
            {method?.allowsInstallments && (
              <select style={{ ...inputStyle, width: 100 }} value={line.installmentId || ""} onChange={(e) => updateLine(line.id, { installmentId: e.target.value || null })}>
                <option value="">À vista</option>
                {data.installments.map((i) => <option key={i.id} value={i.id}>{i.times}x</option>)}
              </select>
            )}
            <button onClick={() => removeLine(line.id)} style={{ background: "none", border: "none", color: C.muted, padding: 8 }}><Trash2 size={15} /></button>
          </div>
        );
      })}
      <button onClick={addLine} style={{ background: "none", border: `1px dashed ${C.line}`, borderRadius: 8, padding: "8px 12px", fontSize: 12, color: C.goldDeep, width: "100%", marginBottom: 10 }}>
        + Adicionar forma de pagamento
      </button>

      <div style={{ fontSize: 12, color: C.muted, marginBottom: 14 }}>
        Total dividido: <strong>{brl(totalPaid)}</strong> · Valor da venda: <strong>{brl(finalPrice)}</strong>
        {Math.abs(diff) > 0.009 && <span style={{ color: diff > 0 ? C.green : C.danger }}> · diferença: {diff > 0 ? "+" : ""}{brl(diff)}</span>}
      </div>

      <label style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 12, fontSize: 13 }}>
        <input type="checkbox" checked={isPartial} onChange={(e) => setIsPartial(e.target.checked)} />
        Pagamento parcial (falta receber parte do valor depois)
      </label>
      {isPartial && (
        <Field label="Data prevista do restante"><input type="date" style={inputStyle} value={dueDate} onChange={(e) => setDueDate(e.target.value)} /></Field>
      )}
      {isPartial && <div style={{ fontSize: 12, color: C.danger, marginBottom: 12 }}>Falta receber (venda − formas lançadas): {brl(pending)}</div>}

      <IconButton variant="gold" style={{ width: "100%", justifyContent: "center" }} onClick={submit} disabled={!product}>Registrar venda</IconButton>
    </Modal>
  );
}

